/**
 * build-catalog.ts — bake the comparemypeps (longevity-signal) catalog snapshot
 * into a compact catalog the website ships with.
 *
 * Source of truth for PRODUCTS / PRICES / SALES:
 *   longevity-signal/docs/data/public-catalog-snapshot.json
 *   (generated by that repo's scripts/export-public-catalog.mjs; refreshed by
 *    its twice-daily "nightly-refresh" cron.)
 *
 * Source of truth for VENDOR IDENTITY / AFFILIATE LINKS / ORDER:
 *   src/data/partners.ts  (the client's curated 16, Sunrise removed)
 *
 * We join the two by slug, attach each vendor's products (compound + vial +
 * live price + on-sale state), build an affiliate-tracked URL for every
 * product, and precompute a "Sale of the Week".
 *
 * Run (dev-time only; the output JSON is committed and shipped):
 *   node --experimental-strip-types scripts/build-catalog.ts [snapshotPath]
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { PARTNERS, HOUSE_BRAND, type Partner } from "../src/data/partners.ts";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const SNAPSHOT =
  process.argv[2] ||
  "/home/user/longevity-signal/docs/data/public-catalog-snapshot.json";
const OUT = path.resolve(__dirname, "../src/data/catalog.json");

/** curated slug -> scraper slug, where they differ */
const SLUG_ALIAS: Record<string, string> = {
  "treasure-coast": "treasure-coast-peptide",
};

/** Directory holding the per-vendor raw catalog files (siblings of the snapshot's parent). */
const RAW_DIR = path.resolve(path.dirname(SNAPSHOT), "..");

/** curated slug -> standalone raw catalog file, for vendors not in the snapshot tables. */
const RAW_CATALOG_FILES: Record<string, string> = {
  "get-melts": "getmelts-raw-catalog.json",
};

type Row = Record<string, unknown>;
interface Snapshot {
  generatedAt: string;
  partners: Row[];
  canonicalCompounds: Row[];
  compoundVariants: Row[];
  partnerListings: Row[];
  listingCurrentStates: Row[];
  catalogReviewRows: Row[];
}

function num(v: unknown): number | null {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

/** Copy query params from the vendor's tracked affiliate URL onto a product URL. */
function withAffiliateRef(productUrl: string, affiliateUrl: string): string {
  try {
    const pu = new URL(productUrl);
    const au = new URL(affiliateUrl);
    const keys = [...au.searchParams.keys()];
    if (keys.length) {
      for (const [k, v] of au.searchParams) pu.searchParams.set(k, v);
      return pu.toString();
    }
    return productUrl;
  } catch {
    return productUrl || affiliateUrl;
  }
}

export interface CatalogProduct {
  id: number;
  compound: string;
  category: string | null;
  size: string;
  mg: number | null;
  form: string | null;
  price: number | null;
  regularPrice: number | null;
  onSale: boolean;
  discountPct: number | null;
  inStock: boolean;
  currency: string;
  url: string;
  observedAt: string | null;
}

export interface CatalogVendor {
  slug: string;
  name: string;
  website: string;
  affiliateUrl: string;
  code: string | null;
  savings: string;
  savingsPct: number | null;
  order: number;
  region?: string;
  comingSoon?: boolean;
  houseBrand?: boolean;
  productCount: number;
  onSaleCount: number;
  cheapest: number | null;
  products: CatalogProduct[];
}

const snap = JSON.parse(fs.readFileSync(SNAPSHOT, "utf8")) as Snapshot;

const partnerBySlug = new Map<string, Row>();
for (const p of snap.partners) partnerBySlug.set(String(p.slug), p);

const compoundById = new Map<number, Row>();
for (const c of snap.canonicalCompounds) compoundById.set(Number(c.id), c);

const variantById = new Map<number, Row>();
for (const v of snap.compoundVariants) variantById.set(Number(v.id), v);

const stateByListing = new Map<number, Row>();
for (const s of snap.listingCurrentStates) stateByListing.set(Number(s.listingId), s);

const listingsByPartner = new Map<number, Row[]>();
for (const l of snap.partnerListings) {
  const arr = listingsByPartner.get(Number(l.partnerId)) ?? [];
  arr.push(l);
  listingsByPartner.set(Number(l.partnerId), arr);
}

// Raw catalog capture (broader coverage than the curated mapped listings).
// Used for vendors that have a scraped catalog but no clean mapped listings yet.
const reviewRowsByPartner = new Map<number, Row[]>();
for (const r of snap.catalogReviewRows ?? []) {
  const arr = reviewRowsByPartner.get(Number(r.partnerId)) ?? [];
  arr.push(r);
  reviewRowsByPartner.set(Number(r.partnerId), arr);
}

function buildProducts(scraperPartner: Row, affiliateUrl: string): CatalogProduct[] {
  const listings = listingsByPartner.get(Number(scraperPartner.id)) ?? [];
  const products: CatalogProduct[] = [];
  for (const l of listings) {
    if (Number(l.active) === 0) continue;
    const compound = compoundById.get(Number(l.compoundId));
    const variant = variantById.get(Number(l.variantId));
    const state = stateByListing.get(Number(l.id));
    const price = num(state?.listPrice);
    const regular = num(state?.regularPrice);
    const inStock = state ? Number(state.inStock) === 1 : false;
    const onSale = !!(price !== null && regular !== null && regular > price && inStock);
    const discountPct =
      onSale && regular ? Math.round(((regular - price!) / regular) * 100) : null;
    const productUrl =
      (l.affiliateProductUrl as string) || (l.productUrl as string) || affiliateUrl;
    products.push({
      id: Number(l.id),
      compound: String(compound?.displayName ?? l.rawName ?? "Peptide"),
      category: (compound?.category as string) ?? null,
      size: String(variant?.label ?? l.rawSize ?? ""),
      mg: num(variant?.totalMg),
      form: (variant?.form as string) ?? null,
      price,
      regularPrice: regular,
      onSale,
      discountPct,
      inStock,
      currency: String(state?.currency ?? "USD"),
      url: withAffiliateRef(productUrl, affiliateUrl),
      observedAt: (state?.observedAt as string) ?? null,
    });
  }
  // On-sale first, then in-stock, then cheapest.
  products.sort((a, b) => {
    if (a.onSale !== b.onSale) return a.onSale ? -1 : 1;
    if (a.inStock !== b.inStock) return a.inStock ? -1 : 1;
    return (a.price ?? Infinity) - (b.price ?? Infinity);
  });
  return products;
}

/** Decode the common HTML entities WooCommerce leaves in raw product names. */
function decodeEntities(s: string): string {
  return String(s)
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&apos;|&#039;/g, "'")
    .replace(/&nbsp;/g, " ")
    .replace(/[\s–—-]+$/, "")
    .trim();
}

/** Split a raw product name into (compound, size) when a trailing dose is present. */
function splitNameSize(raw: string): { compound: string; size: string } {
  const name = decodeEntities(raw);
  const m = name.match(/^(.*?)[\s–—-]+(\d[\d.,]*\s?(?:mg|mcg|ml|iu|g)\b.*)$/i);
  if (m) return { compound: m[1].trim(), size: m[2].trim() };
  return { compound: name, size: "" };
}

/** Placeholder / non-product rows that shouldn't appear on a storefront. */
const JUNK_NAME =
  /^(offer|credit|store credit|gift\s*card|e-?gift|test product|sample|deposit|balance|donation|wallet)\b/i;

const MAX_REVIEW_PRODUCTS = 60;

/** Collapse size variations: group rows by their product-page URL (minus query). */
function pathKey(url: string): string {
  try {
    const u = new URL(url);
    return (u.hostname + u.pathname).replace(/\/+$/, "").toLowerCase();
  } catch {
    return url;
  }
}

/**
 * Build products from the raw catalog-review rows (for vendors without clean
 * mapped listings). One entry per product page; drops junk and placeholders.
 */
function buildProductsFromReviewRows(scraperPartner: Row, affiliateUrl: string): CatalogProduct[] {
  const rows = reviewRowsByPartner.get(Number(scraperPartner.id)) ?? [];
  // Group size-variations of the same product together.
  const groups = new Map<string, Row[]>();
  for (const r of rows) {
    const key = pathKey(String(r.directProductUrl || r.sourceProductKey || r.rawName));
    (groups.get(key) ?? groups.set(key, []).get(key)!).push(r);
  }

  const products: CatalogProduct[] = [];
  for (const group of groups.values()) {
    // Prefer an in-stock, lowest-priced variation to represent the product.
    const best = group
      .filter((r) => num(r.listedPrice) !== null)
      .sort((a, b) => {
        const ia = Number(a.inStock) === 1 ? 0 : 1;
        const ib = Number(b.inStock) === 1 ? 0 : 1;
        if (ia !== ib) return ia - ib;
        return (num(a.listedPrice) ?? Infinity) - (num(b.listedPrice) ?? Infinity);
      })[0];
    if (!best) continue;

    const price = num(best.listedPrice);
    if (price === null || price < 2) continue; // drop $0–$1 placeholders
    const { compound, size } = splitNameSize(String(best.rawName ?? "Product"));
    if (!compound || JUNK_NAME.test(compound)) continue;

    const regular = num(best.regularPrice);
    const inStock = Number(best.inStock) === 1;
    const onSale = !!(regular !== null && regular > price && inStock);
    const discountPct = onSale && regular ? Math.round(((regular - price) / regular) * 100) : null;
    const productUrl = (best.directProductUrl as string) || affiliateUrl;
    products.push({
      id: Number(best.id),
      compound,
      category: null,
      size,
      mg: null,
      form: null,
      price,
      regularPrice: regular,
      onSale,
      discountPct,
      inStock,
      currency: "USD",
      url: withAffiliateRef(productUrl, affiliateUrl),
      observedAt: (best.sourceObservedAt as string) ?? null,
    });
  }
  products.sort((a, b) => {
    if (a.onSale !== b.onSale) return a.onSale ? -1 : 1;
    if (a.inStock !== b.inStock) return a.inStock ? -1 : 1;
    return (a.price ?? Infinity) - (b.price ?? Infinity);
  });
  return products.slice(0, MAX_REVIEW_PRODUCTS);
}

/** Build products from a standalone raw catalog file (Shopify-style export). */
function buildProductsFromRawFile(file: string, affiliateUrl: string): CatalogProduct[] {
  const full = path.join(RAW_DIR, file);
  if (!fs.existsSync(full)) return [];
  const data = JSON.parse(fs.readFileSync(full, "utf8"));
  const rows: Row[] = Array.isArray(data) ? data : ((data.products ?? data.items ?? []) as Row[]);
  const groups = new Map<string, Row[]>();
  for (const r of rows) {
    const key = pathKey(String(r.directProductUrl || r.sourceProductKey || r.rawName));
    (groups.get(key) ?? groups.set(key, []).get(key)!).push(r);
  }
  const products: CatalogProduct[] = [];
  for (const group of groups.values()) {
    const best = group
      .filter((r) => num(r.listedPrice) !== null)
      .sort((a, b) => {
        const ia = Number(a.inStock) === 1 ? 0 : 1;
        const ib = Number(b.inStock) === 1 ? 0 : 1;
        if (ia !== ib) return ia - ib;
        return (num(a.listedPrice) ?? Infinity) - (num(b.listedPrice) ?? Infinity);
      })[0];
    if (!best) continue;
    const price = num(best.listedPrice);
    if (price === null || price < 2) continue;
    const { compound } = splitNameSize(String(best.rawName ?? "Product"));
    if (!compound || JUNK_NAME.test(compound)) continue;
    const rawVariant = String(best.rawVariant ?? "");
    const size = decodeEntities(String(best.rawSize ?? (rawVariant && rawVariant !== "Default Title" ? rawVariant : "")));
    const regular = num(best.compareAtPrice ?? best.regularPrice);
    const inStock = Number(best.inStock) === 1;
    const onSale = !!(regular !== null && regular > price && inStock);
    const discountPct = onSale && regular ? Math.round(((regular - price) / regular) * 100) : null;
    const productUrl = (best.directProductUrl as string) || affiliateUrl;
    const idNum = Number(best.sourceProductKey);
    products.push({
      id: Number.isFinite(idNum) ? idNum : products.length + 1,
      compound,
      category: null,
      size,
      mg: null,
      form: null,
      price,
      regularPrice: regular,
      onSale,
      discountPct,
      inStock,
      currency: "USD",
      url: withAffiliateRef(productUrl, affiliateUrl),
      observedAt: (best.observedAt as string) ?? null,
    });
  }
  products.sort((a, b) => {
    if (a.onSale !== b.onSale) return a.onSale ? -1 : 1;
    if (a.inStock !== b.inStock) return a.inStock ? -1 : 1;
    return (a.price ?? Infinity) - (b.price ?? Infinity);
  });
  return products.slice(0, MAX_REVIEW_PRODUCTS);
}

const curated: Partner[] = [...PARTNERS, HOUSE_BRAND];

const vendors: CatalogVendor[] = curated.map((p, i) => {
  const scraperSlug = SLUG_ALIAS[p.slug] ?? p.slug;
  const sp = partnerBySlug.get(scraperSlug);
  let products: CatalogProduct[] = [];
  const aff = p.affiliateUrl || p.websiteUrl;
  if (sp && !p.comingSoon) {
    const mapped = listingsByPartner.get(Number(sp.id)) ?? [];
    const reviews = reviewRowsByPartner.get(Number(sp.id)) ?? [];
    // Prefer clean mapped listings; fall back to the raw catalog capture.
    products = mapped.length >= 5 || reviews.length === 0
      ? buildProducts(sp, aff)
      : buildProductsFromReviewRows(sp, aff);
  }
  // Vendors with a standalone raw catalog file (not in the snapshot tables).
  if (products.length === 0 && !p.comingSoon && RAW_CATALOG_FILES[p.slug]) {
    products = buildProductsFromRawFile(RAW_CATALOG_FILES[p.slug], aff);
  }
  const onSaleCount = products.filter((x) => x.onSale).length;
  const inStockPrices = products.filter((x) => x.inStock && x.price !== null).map((x) => x.price!);
  return {
    slug: p.slug,
    name: p.name,
    website: p.websiteUrl,
    affiliateUrl: p.affiliateUrl || p.websiteUrl,
    code: p.code,
    savings: p.savings,
    savingsPct: p.savingsPct,
    order: i,
    region: p.region,
    comingSoon: p.comingSoon,
    houseBrand: p.houseBrand,
    productCount: products.length,
    onSaleCount,
    cheapest: inStockPrices.length ? Math.min(...inStockPrices) : null,
    products,
  };
});

// Sale of the Week: biggest in-stock discount across all vendors.
type SalePick = {
  vendorSlug: string;
  vendorName: string;
  code: string | null;
  product: CatalogProduct;
};
let saleOfWeek: SalePick | null = null;
const topDeals: SalePick[] = [];
for (const v of vendors) {
  for (const prod of v.products) {
    if (!prod.onSale || !prod.inStock || prod.discountPct === null) continue;
    const pick: SalePick = { vendorSlug: v.slug, vendorName: v.name, code: v.code, product: prod };
    topDeals.push(pick);
  }
}
topDeals.sort(
  (a, b) =>
    (b.product.discountPct ?? 0) - (a.product.discountPct ?? 0) ||
    (b.product.regularPrice ?? 0) - (b.product.price ?? 0) -
      ((a.product.regularPrice ?? 0) - (a.product.price ?? 0)),
);
saleOfWeek = topDeals[0] ?? null;

const catalog = {
  generatedAt: snap.generatedAt,
  bakedAt: new Date().toISOString(),
  vendorCount: vendors.length,
  productCount: vendors.reduce((n, v) => n + v.productCount, 0),
  saleOfWeek,
  topDeals: topDeals.slice(0, 8),
  vendors,
};

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, `${JSON.stringify(catalog, null, 2)}\n`, "utf8");

const withProducts = vendors.filter((v) => v.productCount > 0).length;
console.log(
  `Wrote ${path.relative(process.cwd(), OUT)} — ${vendors.length} vendors ` +
    `(${withProducts} with products), ${catalog.productCount} products, ` +
    `${topDeals.length} on sale. Sale of week: ${
      saleOfWeek
        ? `${saleOfWeek.vendorName} ${saleOfWeek.product.compound} ${saleOfWeek.product.size} (-${saleOfWeek.product.discountPct}%)`
        : "none"
    }`,
);
